                        diff = list(set(clause1) ^ set(clause2))
                        if len(diff) == 1:
                            new_clauses.append(tuple(sorted(list(set(clause1) - {diff[0]}))))
            if not new_clauses:
                break
            clauses.extend(new_clauses)
        return max(len(clause) for clause in clauses)

